import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const PATCH = "MVP Trainer Pro R11 - Coach Smart Swap v1";
const FILES = [{"target":"src/features/coach/CoachPage.tsx","base64":"","sha256":"268b12a49834e146a66e5f7b1362279f2a572c860de4c858f6ad0c38c22094e8","baselineSha256":"65d452cf96fbba4f653f06d0c6e9af120b1ec9577a0c1a4949515881496d4d44"},{"target":"src/lib/trainingIntelligence.ts","base64":"","sha256":"7f7542d76f33ee4297edc476b6dd8976418bc4bf17f5ac6cf6bd512948d0c7c2","baselineSha256":"1dc6421f63563e8cce508a5830adab662bc3e5ebf3db4431e5e55086a5e627bf"}];

function sha256(buffer) { return crypto.createHash("sha256").update(buffer).digest("hex"); }
function findRepo(start) {
  let current = path.resolve(start);
  for (let i = 0; i < 8; i += 1) {
    if (fs.existsSync(path.join(current,"package.json")) && fs.existsSync(path.join(current,"src"))) return current;
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return null;
}

const repo = findRepo(process.cwd());
if (!repo) {
  console.error("ERROR: Could not find the MVP Trainer repo. Run this installer from the repo root or the scripts folder inside it.");
  process.exit(1);
}

console.log(`\n${PATCH}`);
console.log(`Repo: ${repo}\n`);

let alreadyInstalled = true;
for (const entry of FILES) {
  const target = path.join(repo, entry.target);
  if (!fs.existsSync(target)) {
    console.error(`ERROR: Missing required current file: ${entry.target}`);
    console.error("No files were changed.");
    process.exit(1);
  }
  const currentHash = sha256(fs.readFileSync(target));
  if (currentHash !== entry.sha256) alreadyInstalled = false;
  if (currentHash !== entry.sha256 && currentHash !== entry.baselineSha256) {
    console.error(`ERROR: ${entry.target} is not the exact baseline this R11 installer was built from.`);
    console.error("This safety stop prevents overwriting newer/manual changes. No files were changed.");
    process.exit(1);
  }
}

if (alreadyInstalled) {
  console.log("Already installed. R11 Coach Smart Swap files match the expected hashes.");
  process.exit(0);
}

const stamp = new Date().toISOString().replace(/[:.]/g,"-");
const backupRoot = path.join(repo,".mvp-backups",`r11-coach-smart-swap-${stamp}`);
fs.mkdirSync(backupRoot,{recursive:true});
for (const entry of FILES) {
  const target = path.join(repo,entry.target);
  const backup = path.join(backupRoot,entry.target);
  fs.mkdirSync(path.dirname(backup),{recursive:true});
  fs.copyFileSync(target,backup);
}
for (const entry of FILES) {
  const target = path.join(repo,entry.target);
  const contents = Buffer.from(entry.base64,"base64");
  fs.mkdirSync(path.dirname(target),{recursive:true});
  fs.writeFileSync(target,contents);
  const actual = sha256(fs.readFileSync(target));
  if (actual !== entry.sha256) {
    console.error(`ERROR: Verification failed after writing ${entry.target}`);
    process.exit(1);
  }
  console.log(`OK  ${entry.target}`);
}
console.log(`\nBackup: ${path.relative(repo,backupRoot)}`);
console.log("Frontend install complete.");
console.log("Next: run npm run build from the repo root.\n");
